package com.howierux.mortalexpansion.gametest;
import com.howierux.mortalexpansion.catalog.*;import com.howierux.mortalexpansion.content.*;import com.howierux.mortalexpansion.guide.*;import com.howierux.mortalexpansion.haunt.*;import com.howierux.mortalexpansion.haunt.effects.*;import com.howierux.mortalexpansion.spiritwell.*;import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.gametest.framework.*;import net.minecraft.core.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.*;import net.minecraft.world.InteractionHand;import java.util.*;
public final class RemainingSlicesGameTests implements FabricGameTest {
 static final java.util.Set<BlockPos> DENIED=new java.util.HashSet<>();
 static {net.fabricmc.fabric.api.event.player.PlayerBlockBreakEvents.BEFORE.register((world,p,pos,state,be)->!DENIED.contains(pos));net.fabricmc.fabric.api.transfer.v1.item.ItemStorage.ITEM.registerForItems((stack,context)->{if(!stack.has(net.minecraft.core.component.DataComponents.CUSTOM_DATA))return null;var storage=new net.fabricmc.fabric.api.transfer.v1.storage.base.SingleVariantStorage<net.fabricmc.fabric.api.transfer.v1.item.ItemVariant>(){protected net.fabricmc.fabric.api.transfer.v1.item.ItemVariant getBlankVariant(){return net.fabricmc.fabric.api.transfer.v1.item.ItemVariant.blank();}protected long getCapacity(net.fabricmc.fabric.api.transfer.v1.item.ItemVariant v){return 1;}};var book=EctceteraProgression.book(4);book.set(KnowledgeData.DAMNED_SECRETS,DamnedSecret.ENVY.bit());storage.variant=net.fabricmc.fabric.api.transfer.v1.item.ItemVariant.of(book);storage.amount=1;return storage;},Items.RABBIT_HIDE);}

 static net.minecraft.server.level.ServerPlayer player(GameTestHelper h){var cookie=net.minecraft.server.network.CommonListenerCookie.createInitial(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"remaining-test"),false);var p=new net.minecraft.server.level.ServerPlayer(h.getLevel().getServer(),h.getLevel(),cookie.gameProfile(),cookie.clientInformation());var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);h.getLevel().getServer().getPlayerList().placeNewPlayer(connection,p,cookie);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setPos(h.absolutePos(new BlockPos(1,2,1)).getCenter());return p;}
 static void remove(GameTestHelper h,net.minecraft.server.level.ServerPlayer p){h.getLevel().getServer().getPlayerList().remove(p);}static BlockPos at(GameTestHelper h,int x){return h.absolutePos(new BlockPos(x,2,3));}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void dreamcatcher_owner_strongest_and_removal(GameTestHelper h){var p=player(h);try{var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos.south(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.PURIFIED_DREAMCATCHER.defaultBlockState());var be=(com.howierux.mortalexpansion.blockentity.DreamcatcherBlockEntity)h.getLevel().getBlockEntity(pos);be.setOwner(p.getUUID());h.assertTrue(Dreamcatchers.protectionPercent(p)==100,"Loaded purified catcher protects owner");h.assertTrue(HauntEffects.perform(p,HauntEffectKind.HELPFUL_VISITATION)&&p.getInventory().countItem(CatalogItems.SPIRIT_BOON)==0,"Catches positive event before reward");h.assertTrue(Dreamcatchers.consumeFeedback(p),"Catching reports its own feedback");var saved=be.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(com.howierux.mortalexpansion.blockentity.DreamcatcherBlockEntity)net.minecraft.world.level.block.entity.BlockEntity.loadStatic(pos,be.getBlockState(),saved,h.getLevel().registryAccess());h.assertTrue(p.getUUID().equals(restored.owner()),"Owner persists in native NBT");h.getLevel().removeBlock(pos,false);h.assertTrue(Dreamcatchers.protectionPercent(p)==0,"Breaking immediately clears protection");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void holy_brewing_and_blessing_cooldown(GameTestHelper h){var brew=h.getLevel().potionBrewing();var input=new ItemStack(Items.GLASS_BOTTLE);var bucket=new ItemStack(CatalogItems.HOLY_WATER_BUCKET);h.assertTrue(brew.isIngredient(bucket)&&brew.hasMix(input,bucket),"Native brewing recognizes bucket and empty bottles");var bottle=brew.mix(bucket,input);h.assertTrue(bottle.is(Items.POTION)&&bottle.get(net.minecraft.core.component.DataComponents.POTION_CONTENTS).is(RemainingRuntime.HOLY_POTION),"Brewing delivers Holy Water contents");var splash=brew.mix(new ItemStack(Items.GUNPOWDER),bottle);h.assertTrue(splash.is(Items.SPLASH_POTION)&&splash.get(net.minecraft.core.component.DataComponents.POTION_CONTENTS).is(RemainingRuntime.HOLY_POTION),"Native gunpowder conversion retains consecration");h.assertTrue(!brew.hasMix(new ItemStack(Items.GLASS_BOTTLE,2),bucket),"Oversized bottle stacks cannot delete extras");var p=player(h);try{PlayerHauntManager.setValue(p,25);bottle.finishUsingItem(h.getLevel(),p);h.assertTrue(PlayerHauntManager.getValue(p)==24&&HauntProtection.protectedPlayer(p),"Drinking cleanses and blesses");RemainingRuntime.CONSECRATION.value().applyInstantenousEffect(null,null,p,0,1);h.assertTrue(PlayerHauntManager.getValue(p)==24,"Repeated blessing respects cooldown");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void cauldron_bucket_extraction_does_not_place_fluid(GameTestHelper h){var p=player(h);try{var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos,Blocks.CAULDRON.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.HOLY_WATER_BUCKET));var hit=new net.minecraft.world.phys.BlockHitResult(pos.getCenter(),Direction.UP,pos,false);NaturalPurificationHandler.interact(p,h.getLevel(),InteractionHand.MAIN_HAND,hit);h.assertTrue(p.getMainHandItem().is(Items.BUCKET)&&h.getLevel().getBlockState(pos).is(CatalogBlocks.HOLY_WATER_CAULDRON),"Filled bucket becomes full custom cauldron and empty bucket");NaturalPurificationHandler.interact(p,h.getLevel(),InteractionHand.MAIN_HAND,hit);h.assertTrue(p.getMainHandItem().is(CatalogItems.HOLY_WATER_BUCKET)&&h.getLevel().getBlockState(pos).is(Blocks.CAULDRON)&&h.getLevel().getFluidState(pos.above()).isEmpty(),"Extraction consumes interaction without spilling");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void grave_port_consumes_anchor_and_rejects_replay(GameTestHelper h){var p=player(h);try{var well=at(h,1);var gravePos=at(h,5);h.getLevel().setBlockAndUpdate(well,CatalogBlocks.SPIRITWELL.defaultBlockState());h.getLevel().setBlockAndUpdate(gravePos,CatalogBlocks.GRAVE.defaultBlockState());var grave=(com.howierux.mortalexpansion.travel.GraveEntity)h.getLevel().getBlockEntity(gravePos);grave.placed(p);grave.name(p,p.getGameProfile().getName());h.getLevel().setBlockAndUpdate(gravePos,grave.getBlockState().setValue(CatalogBlocks.GRAVE_NATURAL,true));var frame=gravePos.south(2);h.getLevel().setBlockAndUpdate(frame,CatalogBlocks.MORTAL_GOLEM_BASE.defaultBlockState());((com.howierux.mortalexpansion.blockentity.MortalGolemBaseBlockEntity)h.getLevel().getBlockEntity(frame)).addFlesh(64);for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)h.getLevel().setBlockAndUpdate(gravePos.offset(dx,-1,dz),Blocks.STONE.defaultBlockState());GravePorting.loaded(h.getLevel(),gravePos);p.setPos(well.getCenter());PlayerHauntManager.setValue(p,20);String token=GravePorting.open(p,well);h.assertTrue(!token.isEmpty()&&GravePorting.destinations(p).size()==1,"Only owned natural grave with full anchor is listed");h.assertTrue(GravePorting.choose(p,token,0)&&PlayerHauntManager.getValue(p)==21&&h.getLevel().getBlockState(frame).isAir(),"Port succeeds with one Haunt and consumes complete anchor");h.assertTrue(!GravePorting.choose(p,token,0),"Token replay rejected");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void darkhold_bands_and_gluttony_native_saturation(GameTestHelper h){var p=player(h);try{p.getInventory().setItem(9,EctceteraProgression.book(4));DarkholdProgression.crafted(p,p.getInventory().getItem(9));PlayerHauntManager.setValue(p,130);DarkholdProgression.pulse(p,100);h.assertTrue(p.getAttachedOrCreate(DarkholdProgression.KNOWN)==255,"Carried Darkhold reveals all seven bands by 130");p.getFoodData().setFoodLevel(20);p.getFoodData().setSaturation(20);p.getFoodData().eat(6,1);h.assertTrue(p.canEat(false)&&p.getFoodData().getSaturationLevel()>20,"Native food can exceed saturation cap for Gluttony");p.setAttached(DarkholdProgression.KNOWN,0);p.getFoodData().setSaturation(20);p.getFoodData().eat(6,1);h.assertTrue(!p.canEat(false)&&p.getFoodData().getSaturationLevel()==20,"Ordinary players retain native food limits");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void lust_wrath_pride_and_readonly_envy(GameTestHelper h){var p=player(h);try{p.setAttached(DarkholdProgression.KNOWN,255);var cow=net.minecraft.world.entity.EntityType.COW.create(h.getLevel());cow.setPos(p.position().add(2,0,0));h.getLevel().addFreshEntity(cow);h.assertTrue(DamnedAbilities.breed(p)>0&&cow.isInLove(),"Lust starts native courtship");DamnedAbilities.wrath(p);DamnedAbilities.wrath(p);DamnedAbilities.wrath(p);h.assertTrue(p.getEffect(net.minecraft.world.effect.MobEffects.DAMAGE_BOOST).getAmplifier()==1,"Wrath stacks at Strength II");var state=p.getAttachedOrCreate(RemainingRuntime.ABILITIES);state.putLong("pride_time",h.getLevel().getGameTime()-200);DamnedAbilities.tick(p);h.assertTrue(p.totalExperience==1,"Pride grants slow XP");p.getInventory().setItem(40,new ItemStack(Items.DIAMOND,3));var snapshot=com.howierux.mortalexpansion.network.EnvyPayloads.snapshot(p);snapshot.get(40).shrink(3);h.assertTrue(snapshot.size()==41&&p.getOffhandItem().getCount()==3,"Envy copies all inventory, armor and offhand without mutation");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void greed_breaks_one_real_ore_and_respects_claims(GameTestHelper h){var p=player(h);try{p.setAttached(DarkholdProgression.KNOWN,DamnedSecret.GREED.bit());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND));var pos=at(h,3);h.getLevel().setBlockAndUpdate(pos,Blocks.DIAMOND_ORE.defaultBlockState());h.assertTrue(DamnedAbilities.takeDiamond(p,pos)&&h.getLevel().getBlockState(pos).isAir()&&p.getInventory().countItem(Items.DIAMOND)==2,"Greed consumes native ore and pays exactly one diamond");h.assertTrue(!DamnedAbilities.takeDiamond(p,pos),"Cannot reuse consumed ore");h.getLevel().setBlockAndUpdate(pos,Blocks.DIAMOND_ORE.defaultBlockState());DENIED.add(pos);try{h.assertTrue(!DamnedAbilities.takeDiamond(p,pos)&&h.getLevel().getBlockState(pos).is(Blocks.DIAMOND_ORE)&&p.getInventory().countItem(Items.DIAMOND)==2,"Greed respects Fabric claim cancellation and pays nothing");}finally{DENIED.remove(pos);}h.assertTrue(DamnedAbilities.majority(2)==2&&DamnedAbilities.majority(3)==2,"Day sleep requires strict majority");h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void salt_enclosure_invalidates_when_opened(GameTestHelper h){var center=at(h,3);for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)if(Math.abs(x)==2||Math.abs(z)==2){var p=center.offset(x,0,z);h.getLevel().setBlockAndUpdate(p.below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(p,CatalogBlocks.HOLY_SALT.defaultBlockState());}var zombie=net.minecraft.world.entity.EntityType.ZOMBIE.create(h.getLevel());zombie.setPos(center.getCenter());zombie.tickCount=10;h.getLevel().addFreshEntity(zombie);com.howierux.mortalexpansion.sanctification.SanctifiedAreaHandler.tick(zombie);h.assertTrue(zombie.hasEffect(RemainingRuntime.SANCTIFIED),"Closed salt boundary sanctifies mob");zombie.removeEffect(RemainingRuntime.SANCTIFIED);h.getLevel().removeBlock(center.offset(2,0,0),false);com.howierux.mortalexpansion.sanctification.SanctifiedAreaHandler.tick(zombie);h.assertTrue(!zombie.hasEffect(RemainingRuntime.SANCTIFIED),"Opening boundary invalidates cached interior immediately");h.succeed();}

 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void brewing_stand_fills_three_bottles_and_returns_bucket(GameTestHelper h){var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos,Blocks.BREWING_STAND.defaultBlockState());var be=(net.minecraft.world.level.block.entity.BrewingStandBlockEntity)h.getLevel().getBlockEntity(pos);for(int i=0;i<3;i++)be.setItem(i,new ItemStack(Items.GLASS_BOTTLE));be.setItem(3,new ItemStack(CatalogItems.HOLY_WATER_BUCKET));be.setItem(4,new ItemStack(Items.BLAZE_POWDER));for(int i=0;i<402;i++)net.minecraft.world.level.block.entity.BrewingStandBlockEntity.serverTick(h.getLevel(),pos,be.getBlockState(),be);for(int i=0;i<3;i++)h.assertTrue(be.getItem(i).is(Items.POTION)&&be.getItem(i).get(net.minecraft.core.component.DataComponents.POTION_CONTENTS).is(RemainingRuntime.HOLY_POTION),"Native timed brewing fills all three Holy Water bottles");h.assertTrue(be.getItem(3).is(Items.BUCKET),"Native brewing returns consumed Holy Water bucket");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void grave_port_cross_dimension_revalidates_anchor(GameTestHelper h){var p=player(h);try{var source=at(h,1);h.getLevel().setBlockAndUpdate(source,CatalogBlocks.SPIRITWELL.defaultBlockState());p.setPos(source.getCenter());var other=h.getLevel().getServer().getLevel(net.minecraft.world.level.Level.NETHER);var pos=new BlockPos(48,90,48);other.getChunk(pos);for(int dx=-3;dx<=3;dx++)for(int dz=-3;dz<=3;dz++)for(int dy=-1;dy<=3;dy++)other.setBlockAndUpdate(pos.offset(dx,dy,dz),dy==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());other.setBlockAndUpdate(pos,CatalogBlocks.GRAVE.defaultBlockState());var grave=(com.howierux.mortalexpansion.travel.GraveEntity)other.getBlockEntity(pos);grave.placed(p);grave.name(p,p.getGameProfile().getName());other.setBlockAndUpdate(pos,grave.getBlockState().setValue(CatalogBlocks.GRAVE_NATURAL,true));var frame=pos.east(2);other.setBlockAndUpdate(frame,CatalogBlocks.MORTAL_GOLEM_BASE.defaultBlockState());((com.howierux.mortalexpansion.blockentity.MortalGolemBaseBlockEntity)other.getBlockEntity(frame)).addFlesh(64);GravePorting.loaded(other,pos);String token=GravePorting.open(p,source);h.assertTrue(GravePorting.destinations(p).stream().anyMatch(d->d.dimension().equals("minecraft:the_nether")),"Loaded grave in another dimension is offered");h.assertTrue(GravePorting.choose(p,token,0)&&p.serverLevel()==other&&other.getBlockState(frame).isAir(),"Native teleport crosses dimension and consumes destination frame");h.succeed();}finally{remove(h,p);}}

 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void sloth_native_bed_sleep_sets_night_and_wakes(GameTestHelper h){var p=player(h);long day=h.getLevel().getDayTime();boolean cycle=h.getLevel().getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_DAYLIGHT);try{h.getLevel().getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(true,h.getLevel().getServer());h.getLevel().setDayTime(6000);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.setAttached(DarkholdProgression.KNOWN,DamnedSecret.SLOTH.bit());var foot=at(h,3);h.getLevel().setBlockAndUpdate(foot.below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(foot.east().below(),Blocks.STONE.defaultBlockState());var bed=Blocks.RED_BED.defaultBlockState().setValue(BedBlock.FACING,Direction.EAST);h.getLevel().setBlockAndUpdate(foot,bed);h.getLevel().setBlockAndUpdate(foot.east(),bed.setValue(BedBlock.PART,net.minecraft.world.level.block.state.properties.BedPart.HEAD));p.setPos(foot.getCenter());var result=p.startSleepInBed(foot);h.assertTrue(result.right().isPresent()&&p.isSleeping(),"Native bed accepts daytime Sloth sleeper");for(int i=0;i<102;i++){p.doTick();if(!p.isSleeping())throw new IllegalStateException("Sloth woke on doTick "+i+" active="+DamnedAbilities.canDaySleep(p)+" day="+h.getLevel().getDayTime()+" bed="+h.getLevel().getBlockState(foot));}h.assertTrue(p.isSleeping()&&p.getSleepTimer()>=100,"Daytime sleeper reaches native elapsed timer while morning reset is vetoed");DamnedAbilities.levelTick(h.getLevel());h.assertTrue(Math.floorMod(h.getLevel().getDayTime(),24000)==13000&&!p.isSleeping(),"Majority vote makes night and wakes sleeper");h.succeed();}finally{h.getLevel().setDayTime(day);h.getLevel().getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(cycle,h.getLevel().getServer());remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void custom_cauldron_fluid_transaction_rolls_back(GameTestHelper h){var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.HOLY_WATER_CAULDRON.defaultBlockState());var storage=net.fabricmc.fabric.api.transfer.v1.fluid.FluidStorage.SIDED.find(h.getLevel(),pos,Direction.UP);var fluid=net.fabricmc.fabric.api.transfer.v1.fluid.FluidVariant.of(CatalogFluids.HOLY_WATER.source);try(var tx=net.fabricmc.fabric.api.transfer.v1.transaction.Transaction.openOuter()){h.assertTrue(storage.extract(fluid,net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants.BUCKET,tx)==net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants.BUCKET,"Full custom cauldron exposes native fluid storage");}h.assertTrue(h.getLevel().getBlockState(pos).is(CatalogBlocks.HOLY_WATER_CAULDRON),"Aborted extraction restores full cauldron");try(var tx=net.fabricmc.fabric.api.transfer.v1.transaction.Transaction.openOuter()){storage.extract(fluid,net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants.BUCKET,tx);tx.commit();}h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.CAULDRON),"Committed extraction empties cauldron");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void salt_spirit_circuit_does_not_emit_redstone(GameTestHelper h){var torch=at(h,2);var salt=torch.east();h.getLevel().setBlockAndUpdate(torch.below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(salt.below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(torch,CatalogBlocks.SPIRIT_TORCH.defaultBlockState());h.getLevel().setBlockAndUpdate(salt,CatalogBlocks.HOLY_SALT.defaultBlockState());h.runAfterDelay(5,()->{h.assertTrue(h.getLevel().getBlockState(salt).getValue(net.minecraft.world.level.block.RedStoneWireBlock.POWER)>0,"Spirit torch powers salt circuit");h.assertTrue(Block.getDrops(Blocks.REDSTONE_TORCH.defaultBlockState(),h.getLevel(),torch,null).stream().anyMatch(stack->stack.is(Items.REDSTONE_TORCH)),"Vanilla redstone torch loot is untouched");h.assertTrue(Block.getDrops(CatalogBlocks.SPIRIT_WALL_TORCH.defaultBlockState(),h.getLevel(),torch,null).stream().anyMatch(stack->stack.is(CatalogItems.SPIRIT_TORCH)),"Wall Spirit torch retains its own generated drop table");h.assertTrue(h.getLevel().getBestNeighborSignal(salt)==0,"Spirit circuit emits no vanilla redstone");h.getLevel().removeBlock(torch,false);h.runAfterDelay(5,()->{h.assertTrue(h.getLevel().getBlockState(salt).getValue(net.minecraft.world.level.block.RedStoneWireBlock.POWER)==0,"Removing torch clears salt power");h.succeed();});});}

 @GameTest(template=EMPTY_STRUCTURE,batch="remaining") public void darkhold_in_fabric_storage_exposes_and_shares_read_knowledge(GameTestHelper h){var p=player(h);try{var backpack=new ItemStack(Items.RABBIT_HIDE);backpack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(new net.minecraft.nbt.CompoundTag()));p.getInventory().setItem(9,backpack);p.setAttached(DarkholdProgression.KNOWN,0);PlayerHauntManager.setValue(p,30);DarkholdProgression.pulse(p,100);DarkholdProgression.pulse(p,300);h.assertTrue(PlayerHauntManager.getHundredths(p)==3001&&DamnedSecret.ENVY.unlocked(p),"Read-only Fabric backpack contents apply one exposure pulse and existing revealed knowledge");h.succeed();}finally{remove(h,p);}}
}
